		const visible = text.replace(/\`\`\`(tool|json)[\\s\\S]*?(\`\`\`|$)/g, '').replace(FILLER, '').trim();
		const parts = visible.split(/(\`\`\`[\\s\\S]*?(?:\`\`\`|$))/g);
