		[['files', 'Files', 'workbench.view.explorer'], ['search', 'Search', 'workbench.view.search'], ['agents', 'Agents', 'lightchain.agents.open'], ['board', 'Task board', 'lightchain.tasks.board'], ['layout', 'Layout', '']]
